class EvalError(Exception):
    """Raised when an expression cannot be parsed or evaluated."""
from .errors import EvalError
from .parser import parse


def _apply(op: str, a: int, b: int) -> int:
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if op == "/":
        return a // b
    if op == "%":
        return a % b
    if op == "^":
        return a**b
    raise EvalError(f"unknown operator {op!r}")


def _eval(node) -> int:
    kind = node[0]
    if kind == "num":
        return node[1]
    if kind == "neg":
        return -_eval(node[1])
    if kind == "bin":
        _, op, left, right = node
        return _apply(op, _eval(left), _eval(right))
    raise EvalError(f"bad node {kind!r}")


def evaluate(text: str) -> int:
    """Evaluate an integer expression string."""
    return _eval(parse(text))
from dataclasses import dataclass

from .errors import EvalError

OPERATORS = "+-*/%^()"


@dataclass(frozen=True)
class Token:
    kind: str  # "INT", "OP", or "EOF"
    value: str
    pos: int


def tokenize(text: str) -> list[Token]:
    tokens: list[Token] = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]
        if ch.isspace():
            i += 1
            continue
        if ch.isdigit():
            start = i
            while i < n and text[i].isdigit():
                i += 1
            tokens.append(Token("INT", text[start:i], start))
            continue
        if ch in OPERATORS:
            tokens.append(Token("OP", ch, i))
            i += 1
            continue
        raise EvalError(f"syntax error: unexpected character {ch!r} at {i}")
    tokens.append(Token("EOF", "", n))
    return tokens
"""Recursive-descent parser producing a tiny tuple-based AST.

AST nodes:
    ("num", int)
    ("neg", node)
    ("bin", op, left, right)
